add_action( 'template_redirect', 'perfectpixel_track_recently_viewed', 30 );
add_shortcode( 'recently_viewed_products', 'perfectpixel_recently_viewed_shortcode' );

function perfectpixel_recently_viewed_ids() {
	return isset( $_COOKIE['perfectpixel_recently_viewed'] ) ? wp_parse_id_list( wp_unslash( $_COOKIE['perfectpixel_recently_viewed'] ) ) : array();
}

function perfectpixel_track_recently_viewed() {
	if ( ! is_singular( 'product' ) || headers_sent() ) {
		return;
	}
	$ids   = array_diff( perfectpixel_recently_viewed_ids(), array( get_queried_object_id() ) );
	$ids   = array_slice( array_merge( array( get_queried_object_id() ), $ids ), 0, 20 );
	wc_setcookie( 'perfectpixel_recently_viewed', implode( ',', $ids ), time() + 30 * DAY_IN_SECONDS );
}

function perfectpixel_recently_viewed_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'limit' => 4, 'columns' => 4 ), $atts );
	$ids  = array_diff( perfectpixel_recently_viewed_ids(), array( is_singular( 'product' ) ? get_queried_object_id() : 0 ) );
	$ids  = array_slice( $ids, 0, min( 20, max( 1, absint( $atts['limit'] ) ) ) );
	if ( ! $ids ) {
		return '';
	}
	return do_shortcode( sprintf( '[products ids="%s" columns="%d" orderby="post__in"]', esc_attr( implode( ',', $ids ) ), min( 6, max( 1, absint( $atts['columns'] ) ) ) ) );
}
